INSERT INTO companies SELECT 'SC'||lpad(n::text,3,'0'),'规模五金企业'||lpad(n::text,3,'0'),'工业五金批发',(ARRAY['上海','深圳','苏州','杭州','宁波'])[(n-1)%5+1],date '2015-01-01'+n*30 FROM generate_series(1,20)n ON CONFLICT DO NOTHING;
INSERT INTO products
SELECT tenant_id,'HW-'||lpad(n::text,6,'0'),n,name,category,CASE WHEN n=1 THEN '304不锈钢 / M8×30 / 100枚装' WHEN n=2 THEN '20×47×14mm / 双面橡胶密封' WHEN n=3 THEN '18V / 20–200Nm / 双电池' ELSE '规格S'||n%100||' / 口径'||(5+n%60)||'mm' END,
CASE WHEN n=1 THEN '包' ELSE '件' END,sale_price,CASE WHEN tenant_id='SC002' AND n=1 THEN 99 WHEN tenant_id='SC002' AND n=2 THEN 66 WHEN tenant_id='SC002' AND n=3 THEN 1099 WHEN n=1 THEN 38 WHEN n=2 THEN 16 WHEN n=3 THEN 520 ELSE round(sale_price*.58,2) END,'SUP-'||lpad(((n-1)%40+1)::text,3,'0'),12,
'用于工业设备维护与备件更换；出货前核验型号和规格。'||name||'采用可追溯批次管理，保修12个月，采购成本仅供授权人员查看。'
FROM (SELECT c.tenant_id,n,CASE WHEN n=1 THEN '不锈钢六角螺栓 M8×30' WHEN n=2 THEN '工业轴承 6204-2RS' WHEN n=3 THEN '电动扭矩扳手 18V' ELSE '工业备件-'||lpad(n::text,4,'0') END AS name,
CASE WHEN n=1 THEN '紧固件' WHEN n=2 THEN '轴承' WHEN n=3 THEN '电动工具' ELSE (ARRAY['紧固件','轴承','电动工具','管件','阀门','劳保用品','测量工具','传动件'])[(n-1)%8+1] END category,
CASE WHEN c.tenant_id='SC002' AND n=1 THEN 199 WHEN c.tenant_id='SC002' AND n=2 THEN 129 WHEN c.tenant_id='SC002' AND n=3 THEN 1899 WHEN n=1 THEN 68 WHEN n=2 THEN 29 WHEN n=3 THEN 899 ELSE round(15+(n%500)*1.75,2) END AS sale_price FROM companies c CROSS JOIN generate_series(1,2500)n) p ON CONFLICT DO NOTHING;
INSERT INTO warehouses SELECT c.tenant_id,'W'||w,CASE WHEN w=1 THEN '上海一号仓' WHEN w=2 THEN '深圳二号仓' ELSE '区域仓'||w END,'合成物流园区'||w||'号库房',CASE WHEN w=1 THEN 'E002' ELSE 'E5000' END FROM companies c CROSS JOIN generate_series(1,5)w ON CONFLICT DO NOTHING;
INSERT INTO locations SELECT tenant_id,warehouse_id,'L'||lpad(n::text,3,'0'),'ZONE-'||((n-1)/25+1),(n-1)/10+1,(n-1)%10+1,50000 FROM warehouses CROSS JOIN generate_series(1,100)n ON CONFLICT DO NOTHING;
INSERT INTO inventory SELECT w.tenant_id,w.warehouse_id,w.warehouse_name,'L'||lpad(((p.sku_no-1)%100+1)::text,3,'0'),p.sku,p.name,0,0,CASE WHEN p.sku_no=2 THEN 50 ELSE 100 END,timestamptz '2026-11-05 18:00:00+08' FROM warehouses w JOIN products p USING(tenant_id) ON CONFLICT DO NOTHING;
-- Anchors have stable stock/reservation oracles and are excluded from capacity batches.
UPDATE inventory SET stock=CASE WHEN tenant_id='SC002' AND warehouse_id='W1' AND sku='HW-000001' THEN 9999 WHEN warehouse_id='W1' AND sku='HW-000001' THEN 800 WHEN warehouse_id='W1' AND sku='HW-000002' THEN 42 WHEN warehouse_id='W1' AND sku='HW-000003' THEN 25 WHEN warehouse_id='W2' AND sku='HW-000001' THEN 320 WHEN warehouse_id='W2' AND sku='HW-000002' THEN 180 ELSE substring(warehouse_id from 2)::integer*100+substring(sku from 4)::integer*10 END,
reserved=CASE WHEN tenant_id='SC002' AND warehouse_id='W1' AND sku='HW-000001' THEN 0 WHEN warehouse_id='W1' AND sku='HW-000001' THEN 120 WHEN warehouse_id='W1' AND sku='HW-000002' THEN 10 WHEN warehouse_id='W1' AND sku='HW-000003' THEN 3 WHEN warehouse_id='W2' AND sku='HW-000001' THEN 20 WHEN warehouse_id='W2' AND sku='HW-000002' THEN 30 ELSE 5 END WHERE sku IN ('HW-000001','HW-000002','HW-000003');
INSERT INTO orders SELECT w.tenant_id,prefix||'-ANCHOR-'||warehouse_id,warehouse_id,CASE WHEN prefix='PO' THEN 'purchase' ELSE 'sales' END,CASE WHEN prefix='PO' THEN 'received' ELSE 'shipped' END,timestamptz '2026-11-01 09:00:00+08',CASE WHEN prefix='PO' THEN '演示供应商-锚点批次' ELSE '演示客户-锚点订单' END,manager_employee_id,0,'合成收货地址：工业园区'||warehouse_id,'锚点业务单据，用于固定回归用例，数量与库存账一致。' FROM warehouses w CROSS JOIN (VALUES('PO'),('SO'))v(prefix) ON CONFLICT DO NOTHING;
INSERT INTO orders SELECT tenant_id,'SO-RESERVE-'||warehouse_id,warehouse_id,'sales','allocated',timestamptz '2026-11-05 17:00:00+08','演示客户-待发货',manager_employee_id,0,'合成收货地址：工业园区'||warehouse_id,'已分配但未出库的订单；占用reserved，不计入库存流水。' FROM warehouses ON CONFLICT DO NOTHING;
INSERT INTO order_items
SELECT i.tenant_id,o.order_id,p.sku_no,i.warehouse_id,i.sku,
CASE WHEN o.status='allocated' THEN i.reserved WHEN o.order_type='purchase' THEN i.stock+CASE WHEN i.tenant_id='SC002' AND i.warehouse_id='W1' AND p.sku_no=1 THEN 1 WHEN p.sku_no=1 THEN 200 WHEN p.sku_no=2 THEN 18 ELSE 5 END ELSE CASE WHEN i.tenant_id='SC002' AND i.warehouse_id='W1' AND p.sku_no=1 THEN 1 WHEN p.sku_no=1 THEN 200 WHEN p.sku_no=2 THEN 18 ELSE 5 END END,
CASE WHEN o.order_type='purchase' THEN p.cost_price ELSE p.sale_price END,0
FROM inventory i JOIN products p USING(tenant_id,sku) JOIN orders o ON o.tenant_id=i.tenant_id AND o.warehouse_id=i.warehouse_id WHERE p.sku_no<=3 AND (o.status<>'allocated' OR i.reserved>0) ON CONFLICT DO NOTHING;
UPDATE order_items SET line_total=quantity*unit_price WHERE line_total=0;
UPDATE orders o SET total_amount=x.amount FROM (SELECT tenant_id,order_id,sum(line_total) amount FROM order_items GROUP BY tenant_id,order_id)x WHERE o.tenant_id=x.tenant_id AND o.order_id=x.order_id;
INSERT INTO stock_movements SELECT i.tenant_id,'MOV-'||i.order_id||'-'||i.line_no,i.warehouse_id,v.location_id,i.sku,CASE WHEN o.order_type='purchase' THEN 'inbound' ELSE 'outbound' END,i.quantity,CASE WHEN o.order_type='purchase' THEN timestamptz '2026-11-01 09:30:00+08' ELSE timestamptz '2026-11-05 15:30:00+08' END,o.order_id,o.order_id,i.line_no,o.employee_id,CASE WHEN o.order_type='purchase' THEN '采购收货并验收上架' ELSE '销售订单复核后出库' END FROM order_items i JOIN orders o USING(tenant_id,order_id) JOIN inventory v ON v.tenant_id=i.tenant_id AND v.warehouse_id=i.warehouse_id AND v.sku=i.sku WHERE o.status IN('received','shipped') ON CONFLICT DO NOTHING;
INSERT INTO after_sales SELECT tenant_id,'AS-ANCHOR-'||warehouse_id,warehouse_id,'SO-ANCHOR-'||warehouse_id,3,'HW-000003','演示客户-锚点订单',timestamptz '2026-11-05 17:30:00+08','open','battery','电池无法充电，客户已提交检测申请，尚未退货或改变库存。',date '2027-11-05','等待工程师检测；保修12个月。' FROM warehouses ON CONFLICT DO NOTHING;
